    /// A reference to `input` is stored in the parser for scanning.
    /// `parser_arena` is where the parser's internal objects (GSS, SPPF nodes,
    /// etc.) are allocated.
    pub fn new(input: &'i Input, parser_arena: &'arena Arena) -> Self {
        init_logger();
        let vec_arena = parser_arena;
        Self {
            vec_arena,
            scanner: CyclesScanner::new(input, vec_arena),
            gss_nodes_index: LazyInlineMaps::new(74, vec_arena),
            descriptors: vec_arena.vec_with_capacity(
                input.len() as usize / DESCRIPTORS_CAPACITY_DIVISOR + DESCRIPTORS_CAPACITY_FLOOR,
            ),
            gss_nodes: vec_arena.vec_with_capacity(input.len() as usize * GSS_CAPACITY_MULTIPLIER),
            sppf_nodes: vec_arena
                .vec_with_capacity(input.len() as usize * SPPF_CAPACITY_MULTIPLIER),
            intermediate_nodes_index: LazyInlineMaps::new(199, vec_arena),
            dd_intermediate_nodes_index: LazyInlineMaps::new(0, vec_arena),
            terminal_nodes_index: LazyInlineMaps::new(4, vec_arena),
            epsilon_nodes: {
                let mut v = vec_arena.vec_with_capacity(input.len() as usize + 1);
                v.resize(input.len() as usize + 1, SPPFNodeId::NONE);
                v
            },
            #[cfg(feature = "instrument")]
            descriptors_count: 0,
            #[cfg(feature = "instrument")]
            descriptors_peak: 0,
            #[cfg(feature = "instrument")]
            ll1_call_log: vec![],
            intermediate_nodes_children: vec_arena.vec(),
            intermediate_nodes_children_map: OnceCell::new(),
            nonterminal_nodes_children: vec_arena.vec(),
            nonterminal_nodes_children_map: OnceCell::new(),
            envs: vec_arena.vec(),
            failures: InlineVec::Empty,
            suppress_failures: false,
            #[cfg(feature = "debug-trace")]
            trace_events: None,
        }
    }
