    fn parse_ordinary_ll1(
        &mut self,
        i: u32,
        failure_context: Option<(SlotId, Option<GssNodeId>)>,
    ) -> Option<SPPFNodeId> {
        #[cfg(feature = "instrument")]
        self.ll1_call_log.push((NonterminalId(28), i));
        let result = (|| -> Option<SPPFNodeId> {
            let matched = self.scanner.longest_match(&FIRST_SET_ORDINARY, i)?;
            match matched {
                TerminalId(0) => {
                    let mut j = i;
                    let right_child = {
                        let start = j;
                        let (end, node) =
                            self.match_terminal(TerminalId(0), start, SlotId(95), None)?;
                        j = end;
                        node
                    };
                    let left_extent = self.sppf_node(right_child).left_extent();
                    let current = right_child;
                    Some(self.add_nonterminal_node(NonterminalNode {
                        nonterminal_id: NonterminalId(28),
                        return_slot: SlotId(95),
                        span: Span {
                            left_extent,
                            right_extent: j,
                        },
                        child: current,
                        ambiguous: false,
                    }))
                }
                _ => unreachable!("LL(1) dispatch covers every terminal in FIRST_SET"),
            }
        })();
        if result.is_none() {
            if let Some((slot_id, gss_node_id)) = failure_context {
                self.add_failure(
                    i,
                    slot_id,
                    gss_node_id,
                    GLLFailureKind::UnexpectedToken(&FIRST_SET_ORDINARY),
                );
            }
        }
        result
    }
    fn get_or_create_epsilon_node(&mut self, i: u32) -> SPPFNodeId {
        let existing = self.epsilon_nodes[i as usize];
        if existing != SPPFNodeId::NONE {
            record!(self, TerminalNodeFound, existing);
            return existing;
        }
        let span = Span::new(i, i);
        let terminal_id = TerminalId(2);
        let node_id = SPPFNodeId(self.sppf_nodes.len() as u32);
        record!(self, TerminalNodeCreated, terminal_id, span);
        self.sppf_nodes
            .push(SPPFNode::Terminal(TerminalNode { terminal_id, span }));
        self.epsilon_nodes[i as usize] = node_id;
        node_id
    }
